import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { Link } from "./link";
import { IContentfulLink } from "@/core/types/contentful-types";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const contentfulInternalLink = {
  title: "Öppettider (från Contentful)",
  internalLink: { slug: "/oppettider" },
} satisfies IContentfulLink;

const contentfulExternalLink = {
  title: "Parks and Resorts (från Contentful)",
  externalUrl: "https://www.parksandresorts.com",
  openInNewTab: true,
} satisfies IContentfulLink;

const meta = {
  title: "Primitives/Link",
  component: Link,
  parameters: {
    docs: {
      description: {
        component:
          "Anchor that picks its target from `contentfulLink`, else `internalLink`, else `externalLink`. An " +
          "internal path renders with Gatsby's Link for client-side navigation, while external URLs and links " +
          'that open in a new tab render as a plain anchor with `rel="noreferrer"`. The text is `children` when ' +
          "given, otherwise `title`. When none of the three link props resolve to a target the component renders " +
          "only its children, so a card or list item can pass an optional link without branching. Other anchor " +
          "attributes are passed through.",
      },
    },
  },
  argTypes: {
    className: { table: { disable: true } },
  },
  args: {
    internalLink: "/attraktioner",
    title: "Attraktioner",
    openInNewTab: false,
  },
} satisfies Meta<typeof Link>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const link = canvas.getByRole("link", { name: "Attraktioner" });
    await expect(link).toHaveAttribute("href", "/attraktioner");
  },
};

export const VariantLinkTypes: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout
      title="Link source and rendering (contentfulLink > internalLink > externalLink)"
      variantType="other"
    >
      <Variant label="internalLink (Gatsby Link)">
        <Link {...args} />
      </Variant>
      <Variant label="internalLink + openInNewTab (plain anchor, target _blank)">
        <Link {...args} openInNewTab />
      </Variant>
      <Variant label="externalLink (plain anchor, rel noreferrer)">
        <Link
          {...args}
          internalLink={undefined}
          externalLink="https://www.parksandresorts.com"
          title="Parks and Resorts"
        />
      </Variant>
      <Variant label="contentfulLink with internalLink slug">
        <Link {...args} internalLink={undefined} title={undefined} contentfulLink={contentfulInternalLink} />
      </Variant>
      <Variant label="contentfulLink with externalUrl and openInNewTab">
        <Link {...args} internalLink={undefined} title={undefined} contentfulLink={contentfulExternalLink} />
      </Variant>
      <Variant label="children instead of title">
        <Link {...args}>
          <strong>Attraktioner</strong> (children)
        </Link>
      </Variant>
      <Variant label="no link props: children rendered without an anchor">
        <Link {...args} internalLink={undefined} title={undefined}>
          Bara text, ingen länk
        </Link>
      </Variant>
    </ShowcaseLayout>
  ),
};

export const TestExternalLinkAttributes: Story = {
  args: {
    internalLink: undefined,
    externalLink: "https://www.parksandresorts.com",
    title: "Parks and Resorts",
    openInNewTab: true,
  },
  // Behaviour only: an external link opened in a new tab must carry the new-tab and referrer attributes.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const link = canvas.getByRole("link", { name: "Parks and Resorts" });
    await expect(link).toHaveAttribute("href", "https://www.parksandresorts.com");
    await expect(link).toHaveAttribute("target", "_blank");
    await expect(link).toHaveAttribute("rel", "noreferrer");
  },
};

export const TestFallbackWithoutLink: Story = {
  args: {
    internalLink: undefined,
    title: undefined,
    children: "Bara text, ingen länk",
  },
  // Behaviour only: without a target the children are rendered as-is, with no anchor around them.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByText("Bara text, ingen länk")).toBeInTheDocument();
    await expect(canvas.queryByRole("link")).not.toBeInTheDocument();
  },
};
